public StrBuilder ensureCapacity(int capacity) {
    if (capacity > buffer.length) {
        char[] old = buffer;
        buffer = new char[capacity];
        System.arraycopy(old, 0, buffer, 0, size);
    }
    return this;
}

public String toString() {
    return new String(buffer, 0, size);
}

